from openpyxl import load_workbook

# Load the workbook and select the active worksheet
wb = load_workbook('input.xlsx')
ws = wb['Sheet1']

# Iterate through each cell in column B (column index 1)
for row in ws.iter_rows(min_col=2, max_col=2):
    cell = row[0]
    if cell.value is not None:
        # Check if the cell value is a string and not a date
        if isinstance(cell.value, str):
            # Try to extract the numeric part
            # Pattern: [A-Z]{2} [0-9]+ or [A-Z]{3}[0-9]+ or [A-Z]{2} [0-9]+
            # We'll split the string to find the numeric part
            parts = cell.value.split()
            if len(parts) == 1:
                # Check if it's a 3-letter code followed by a number
                if len(parts[0]) >= 4 and parts[0][-1].isdigit():
                    number = parts[0][-1]
                else:
                    number = ''
            else:
                # Check if it's a 2-letter code followed by a number
                if len(parts[0]) == 2 and parts[1].isdigit():
                    number = parts[1]
                else:
                    number = ''
            # If a number was found, replace the cell value with it
            if number:
                cell.value = number

