from openpyxl import load_workbook
from openpyxl.styles import PatternFill

# Load the workbook
wb = load_workbook('input.xlsx')
datensatz_sheet = wb['Datensatz']
analyse_sheet = wb['Analyse']

# Get the product list from the 'Datensatz' sheet
products = [cell.value for cell in datensatz_sheet[3][1:]]  # Row 3, columns C to K

# Create a dictionary to store the product indices
product_to_index = {product: idx for idx, product in enumerate(products, start=1)}

# Get the number of customers
num_customers = 30  # From the data provided

# Initialize a 8x8 matrix to store co-occurrence counts
co_occurrence = [[0] * 8 for _ in range(8)]

# Iterate through each customer
for row in range(4, 34):  # Rows 4 to 33 (Customer 1 to 30)
    customer_row = datensatz_sheet[row]
    for i in range(1, 9):  # Columns C to K (Product 1 to 8)
        product1 = customer_row[i].value
        if product1 <= 0:
            continue
        product1_idx = product_to_index[products[i - 1]]
        for j in range(1, 9):  # Columns C to K (Product 1 to 8)
            product2 = customer_row[j].value
            if product2 <= 0:
                continue
            product2_idx = product_to_index[products[j - 1]]
            if product1_idx != product2_idx:
                co_occurrence[product1_idx - 1][product2_idx - 1] += 1

# Calculate the total number of customers who bought each product
product_counts = [0] * 8
for i in range(8):
    for j in range(8):
        product_counts[i] += co_occurrence[i][j]

# Calculate the cross-selling percentages
percentage_matrix = [[0.0] * 8 for _ in range(8)]
for i in range(8):
    for j in range(8):
        if product_counts[i] == 0:
            percentage_matrix[i][j] = 0.0
        else:
            percentage_matrix[i][j] = co_occurrence[i][j] / product_counts[i]

# Apply formatting: keep 9 decimal places, omit trailing 0, and no decimal places if value is 1
formatted_matrix = [[0.0] * 8 for _ in range(8)]
for i in range(8):
    for j in range(8):
        val = percentage_matrix[i][j]
        if val == 1.0:
            formatted_matrix[i][j] = 1
        else:
            formatted_matrix[i][j] = round(val, 9)

# Write the formatted values to the 'Analyse' sheet
for i in range(8):
    for j in range(8):
        cell = analyse_sheet[f'D{i + 5}'] if j == 0 else analyse_sheet[f'E{i + 5}']
        cell.value = formatted_matrix[i][j]

# Apply color to D5:K12
fill = PatternFill(start_color="F2F2F2", end_color="F2F2F2", fill_type="solid")
for row in range(5, 13):  # Rows 5 to 12
    for col in range(3, 11):  # Columns D to K (3 to 10)
        cell = analyse_sheet[analyse_sheet.cell(row=row, column=col).coordinate]
        cell.fill = fill

# Save the workbook
wb.save('output.xlsx')
