from openpyxl import load_workbook

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Define the range for processing
start_row = 2
end_row = 41
name_col = 'C'  # Column C for Name
entry_time_col = 'I'  # Column I for Entry Time
max_col = 'M'  # Column M for Max

# Dictionary to store the latest entry time for each name
latest_entry_times = {}

# Iterate through the rows to find the latest entry time for each name
for row in range(start_row, end_row + 1):
    name = ws[f'{name_col}{row}'].value
    entry_time = ws[f'{entry_time_col}{row}'].value
    if name is not None and entry_time is not None:
        # Convert entry_time to a comparable format (datetime)
        if isinstance(entry_time, str):
            try:
                entry_time = float(entry_time)
            except ValueError:
                entry_time = None
        if entry_time is not None:
            if name not in latest_entry_times or entry_time > latest_entry_times[name]:
                latest_entry_times[name] = entry_time

# Write the computed values to the Max column
for row in range(start_row, end_row + 1):
    name = ws[f'{name_col}{row}'].value
    if name in latest_entry_times:
        if ws[f'{entry_time_col}{row}'].value == latest_entry_times[name]:
            ws[f'{max_col}{row}'] = 'Latest'
        else:
            ws[f'{max_col}{row}'] = 'Not Latest'
    else:
        ws[f'{max_col}{row}'] = ''

# Save the workbook
wb.save('output.xlsx')
